-- B isolated H2 fixture copied from existing system test schema.
CREATE TABLE IF NOT EXISTS "gxp_audit_event" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" bigint NOT NULL,
    "ledger_sequence" bigint NOT NULL,
    "operation_id" varchar(128) NOT NULL,
    "domain" varchar(64) NOT NULL,
    "subject_type" varchar(64) NOT NULL,
    "subject_id" varchar(256) NOT NULL,
    "subject_version" varchar(128) NOT NULL,
    "action" varchar(64) NOT NULL,
    "reason" varchar(500) NOT NULL,
    "actor_id" bigint NOT NULL,
    "actor_username" varchar(64) NOT NULL,
    "actor_display_name" varchar(128) NOT NULL,
    "server_occurred_at" timestamp NOT NULL,
    "before_state" varchar(32) NOT NULL,
    "before_object_version" varchar(128),
    "before_state_json" clob,
    "after_state" varchar(32) NOT NULL,
    "after_object_version" varchar(128),
    "after_state_json" clob,
    "policy_version" varchar(128) NOT NULL,
    "idempotency_key" varchar(128) NOT NULL,
    "request_id" varchar(128),
    "signature_record_id" varchar(128),
    "signature_content_hash" varchar(128),
    "idempotency_payload_hash" varchar(64) NOT NULL,
    "canonical_event_json" clob NOT NULL,
    "previous_event_hash" varchar(64),
    "event_hash" varchar(64) NOT NULL,
    "algorithm" varchar(32) NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    UNIQUE ("tenant_id", "ledger_sequence"),
    UNIQUE ("tenant_id", "idempotency_key")
) COMMENT 'GxP 统一审计事件只追加账本';

CREATE TABLE IF NOT EXISTS "gxp_audit_ledger_sequence" (
    "tenant_id" bigint NOT NULL,
    "next_ledger_sequence" bigint NOT NULL,
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("tenant_id")
) COMMENT 'GxP 审计账本序号水位';

CREATE TABLE IF NOT EXISTS "gxp_audit_policy_operation" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" bigint NOT NULL,
    "policy_version" varchar(128) NOT NULL,
    "operation_id" varchar(128) NOT NULL,
    "source_type" varchar(64) NOT NULL,
    "source_locator" varchar(512) NOT NULL,
    "domain" varchar(64) NOT NULL,
    "subject_type" varchar(64) NOT NULL,
    "action_type" varchar(64) NOT NULL,
    "reason_policy" varchar(64) NOT NULL,
    "signature_policy" varchar(64) NOT NULL,
    "state_policy" varchar(64) NOT NULL,
    "retention_class" varchar(64) NOT NULL,
    "test_ids" varchar(512) NOT NULL,
    "owner" varchar(128) NOT NULL,
    "applicability" varchar(64) NOT NULL,
    "active" bit NOT NULL DEFAULT TRUE,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    UNIQUE ("tenant_id", "operation_id", "policy_version")
) COMMENT 'GxP 审计策略操作登记';
